import React, { useState } from 'react';
// UI library
import { Card, Form, Button, Row, Col } from 'react-bootstrap';

const ControlsPanel = ({
    onStartSimulation,
    algorithms = [],
    onAlgorithmChange,
    parameters = {},
    onParameterChange,
    loading = false
}) => {

    const [selectedAlgorithm, setSelectedAlgorithm] = useState(algorithms?.[0] || "");

    const handleStartClick = () => {
        if (onStartSimulation) {
            onStartSimulation(selectedAlgorithm, parameters);
        }
    };

    const handleAlgorithmChange = (event) => {
        const algorithm = event.target.value;
        setSelectedAlgorithm(algorithm);
        if (onAlgorithmChange) onAlgorithmChange(algorithm);
    };

    const handleParameterChange = (event) => {
        const { name, value } = event.target;
        if (onParameterChange) onParameterChange(name, value);
    };

    return (
        <Card className="mb-4" border="secondary">
            <Card.Body>
                <Card.Title>Simulation Controls</Card.Title>
                <Form>
                    <Form.Group as={Row} className="mb-3" controlId="algorithm-select">
                        <Form.Label column sm="3">
                            Algorithm
                        </Form.Label>
                        <Col sm="9">
                            <Form.Select
                                value={selectedAlgorithm}
                                onChange={handleAlgorithmChange}
                                disabled={loading}
                            >
                                {algorithms.map((algorithm) => (
                                    <option key={algorithm} value={algorithm}>
                                        {algorithm}
                                    </option>
                                ))}
                            </Form.Select>
                        </Col>
                    </Form.Group>

                    <fieldset disabled={loading}>
                        <legend>Parameters</legend>
                        {Object.keys(parameters).map((param) => (
                            <Form.Group as={Row} className="mb-2" controlId={param} key={param}>
                                <Form.Label column sm="3">
                                    {param}
                                </Form.Label>
                                <Col sm="9">
                                    <Form.Control
                                        type="number"
                                        name={param}
                                        value={parameters[param]}
                                        onChange={handleParameterChange}
                                    />
                                </Col>
                            </Form.Group>
                        ))}
                    </fieldset>

                    <Button
                        variant="primary"
                        onClick={handleStartClick}
                        disabled={loading}
                    >
                        {loading ? 'Running...' : 'Start Simulation'}
                    </Button>
                </Form>
            </Card.Body>
        </Card>
    );
};

export default ControlsPanel;
